import fs from "fs/promises";
import path from "path";
import { DocxTemplate, TemplateImage } from "./docx-template";
import type { ActivityReportTemplate } from "@/lib/auth/report-template";

/**
 * Activity reports are generated by filling the school's original Word forms,
 * so the downloaded file is an exact copy of the official template:
 *  - SPECIALIST: petrol form "تقرير البرامج والأنشطة اللامنهجية" (إدارة شؤون المدارس header)
 *  - ANNUAL:     maroon form "تقرير الأنشطة اللاصفية" with the school header (teachers)
 */
const TEMPLATE_FILES: Record<ActivityReportTemplate, string> = {
  SPECIALIST: "activity-report-specialist.docx",
  ANNUAL: "activity-report-annual.docx",
};

export interface ActivityReportStudent {
  personal_number: string;
  name: string;
  class_name: string;
  nationality: string;
  attendance: string;
}

export interface ActivityWordExportData {
  school_name: string;
  academic_year?: string | null;
  name: string;
  activity_date: string;
  time_period?: string;
  activity_type: string;
  activity_type_other?: string;
  target_group: string;
  total_participants: number;
  qatari_count: number;
  non_qatari_count: number;
  responsible_department: string;
  external_entity: string;
  external_honored: boolean;
  parent_participation: boolean;
  activation_method: string;
  activation_method_other?: string;
  objectives: string;
  execution_steps: string;
  safety_measures: string;
  student_satisfaction: number;
  activity_quality: number;
  recommendations: string;
  photos: TemplateImage[];
  students: ActivityReportStudent[];
}

const ARABIC_DAYS = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت"];

function formatDate(value: string) {
  const d = new Date(value);
  const dd = String(d.getUTCDate()).padStart(2, "0");
  const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
  return { day: ARABIC_DAYS[d.getUTCDay()], date: `${dd}/${mm}/${d.getUTCFullYear()}` };
}

function clampRating(value: number) {
  return Math.min(5, Math.max(1, Math.round(Number(value) || 5)));
}

/** "أخرى" text: the free-text value, or the chosen option when the template has no box for it. */
function otherText(selected: string, other: string | undefined) {
  if (selected === "أخرى") return other || "";
  return [selected, other].filter(Boolean).join(" - ");
}

async function loadTemplate(template: ActivityReportTemplate) {
  const file = path.join(process.cwd(), "templates", "reports", TEMPLATE_FILES[template]);
  return DocxTemplate.load(await fs.readFile(file));
}

// ------------------------------------- MAROON form (school header) → ANNUAL / teacher

const MAROON = {
  main: 1,
  photos: 2,
  students: 4,
  stats: 5,
  // [row, cell] of each activity-type checkbox
  activityTypes: {
    "خطة معتمدة": [3, 1],
    "مناسبة": [3, 2],
    "طلب إدراج": [3, 3],
    "هوية وطنية": [3, 4],
    "قيم تربوية": [3, 5],
    "تعميم": [4, 1],
    "خطط أقسام": [4, 2],
    "بحث علمي": [4, 3],
  } as Record<string, [number, number]>,
  activityTypeOther: [4, 4] as [number, number],
  activityTypeOtherText: [4, 5] as [number, number],
  activationMethods: {
    "ورشة": 1,
    "مسابقة": 2,
    "فعالية": 3,
    "محاضرة": 4,
    "رحلة": 5,
  } as Record<string, number>,
  activationOtherCell: 6,
};

async function fillMaroonForm(data: ActivityWordExportData) {
  const doc = await loadTemplate("ANNUAL");
  const t = MAROON.main;
  const { day, date } = formatDate(data.activity_date);

  if (data.academic_year && /^\d{4}-\d{4}$/.test(data.academic_year)) {
    doc.replaceText("2026 – 2027", data.academic_year.replace("-", " – "));
  }

  doc.setCellText(t, 1, 1, day);
  doc.setCellText(t, 1, 3, date);
  doc.setCellText(t, 2, 1, data.name);
  doc.setCellText(t, 2, 3, data.time_period);

  const typeCell = MAROON.activityTypes[data.activity_type];
  if (typeCell) {
    doc.checkContentControl(t, typeCell[0], typeCell[1]);
  } else {
    doc.checkContentControl(t, ...MAROON.activityTypeOther);
    doc.setCellText(t, ...MAROON.activityTypeOtherText, otherText(data.activity_type, data.activity_type_other));
  }

  doc.setCellText(t, 5, 1, data.target_group);
  doc.setCellText(t, 5, 4, String(data.qatari_count));
  doc.setCellText(t, 5, 6, String(data.non_qatari_count));
  doc.setCellText(t, 6, 1, data.external_entity);
  doc.setCellText(t, 6, 3, data.responsible_department);

  const methodCell = MAROON.activationMethods[data.activation_method];
  if (methodCell) {
    doc.checkContentControl(t, 7, methodCell);
  } else {
    doc.checkContentControl(t, 7, MAROON.activationOtherCell);
    // Short label keeps the narrow "أخرى تكتب" cell on one line
    const method = data.activation_method === "عن بُعد (افتراضي)" ? "عن بُعد" : data.activation_method;
    doc.appendToParagraph(t, 7, MAROON.activationOtherCell, "أخرى", otherText(method, data.activation_method_other));
  }

  doc.setCellText(t, 8, 1, data.objectives);
  doc.setCellText(t, 9, 1, data.execution_steps);
  doc.setCellText(t, 10, 1, data.safety_measures);
  // Rating cells run 1 (غير راض أبداً) … 5 (راضٍ جداً)
  doc.checkContentControl(t, 11, clampRating(data.student_satisfaction));
  doc.checkContentControl(t, 12, clampRating(data.activity_quality));
  doc.setCellText(t, 13, 1, data.recommendations);

  const photoSlots: [number, number][] = [[1, 0], [1, 1], [2, 0], [2, 1]];
  data.photos.slice(0, 4).forEach((photo, i) => {
    doc.setCellImage(MAROON.photos, photoSlots[i][0], photoSlots[i][1], photo, 3.5, 2.4);
  });

  // Participants list: 12 rows in the template, extra rows are cloned from the last one
  const templateRows = doc.rowCount(MAROON.students) - 1;
  for (let i = templateRows; i < data.students.length; i++) {
    doc.cloneRow(MAROON.students, templateRows);
  }
  data.students.forEach((s, i) => {
    const r = i + 1;
    doc.setCellText(MAROON.students, r, 1, s.personal_number);
    doc.setCellText(MAROON.students, r, 2, s.name);
    doc.setCellText(MAROON.students, r, 3, s.class_name);
    doc.setCellText(MAROON.students, r, 4, s.nationality);
    doc.setCellText(MAROON.students, r, 5, s.attendance);
  });

  doc.setCellText(MAROON.stats, 1, 0, String(data.qatari_count));
  doc.setCellText(MAROON.stats, 1, 1, String(data.non_qatari_count));
  doc.setCellText(MAROON.stats, 1, 2, String(data.total_participants));

  return doc.toBuffer();
}

// ------------------- PETROL form (إدارة شؤون المدارس header) → SPECIALIST

// Checkboxes in this form are floating shapes, addressed by their wp:docPr id
const PETROL = {
  activityTypes: {
    "خطة معتمدة": "680292110",
    "مناسبة": "1189704422",
    "هوية وطنية": "1131448178",
    "قيم تربوية": "459654018",
    "تعميم": "750978751",
  } as Record<string, string>,
  activityTypeOther: "25568201",
  activationMethods: {
    "ورشة": "2",
    "مسابقة": "5",
    "فعالية": "6",
    "محاضرة": "11",
    "رحلة": "2057410897",
    "عن بُعد (افتراضي)": "734165847",
  } as Record<string, string>,
  parentNo: "1055725194",
  parentYes: "551076819",
  honoredNo: "475898669",
  honoredYes: "863001074",
  // Photo frames in reading order: top-right, top-left, bottom-right, bottom-left
  photoFrames: ["7", "8", "10", "9"],
};

async function fillPetrolForm(data: ActivityWordExportData) {
  const doc = await loadTemplate("SPECIALIST");
  const t = 0;
  const { day, date } = formatDate(data.activity_date);

  if (data.academic_year && /^\d{4}-\d{4}$/.test(data.academic_year)) {
    doc.replaceText("2026-2027", data.academic_year);
  }

  doc.setCellText(t, 0, 0, data.school_name);
  doc.setCellText(t, 1, 0, date);
  doc.setCellText(t, 1, 2, day);
  doc.setCellText(t, 2, 0, data.name);

  const typeBox = PETROL.activityTypes[data.activity_type];
  if (typeBox) {
    doc.overlayCheckMark(typeBox);
  } else {
    doc.overlayCheckMark(PETROL.activityTypeOther);
    doc.fillParentheses(t, 3, 0, "تذكر", otherText(data.activity_type, data.activity_type_other));
  }

  doc.setCellText(t, 4, 0, String(data.non_qatari_count));
  doc.setCellText(t, 4, 2, String(data.qatari_count));
  doc.setCellText(t, 4, 4, String(data.total_participants));
  doc.setCellText(t, 4, 6, data.target_group);
  doc.setCellText(t, 5, 0, data.responsible_department);
  doc.setCellText(t, 5, 2, data.external_entity);

  doc.overlayCheckMark(data.parent_participation ? PETROL.parentYes : PETROL.parentNo);
  doc.overlayCheckMark(data.external_honored ? PETROL.honoredYes : PETROL.honoredNo);

  const methodBox = PETROL.activationMethods[data.activation_method];
  if (methodBox) {
    doc.overlayCheckMark(methodBox);
  } else {
    doc.fillParentheses(t, 7, 0, "تذكر", otherText(data.activation_method, data.activation_method_other));
  }

  doc.setCellText(t, 8, 0, data.objectives);
  doc.setCellText(t, 9, 0, data.execution_steps);
  doc.setCellText(t, 10, 0, data.safety_measures);
  // Rating cells run 5 (راضٍ جداً) … 1 (غير راض أبداً)
  doc.setCellText(t, 12, 5 - clampRating(data.student_satisfaction), "✔");
  doc.setCellText(t, 14, 5 - clampRating(data.activity_quality), "✔");
  doc.setCellText(t, 15, 0, data.recommendations);

  data.photos.slice(0, 4).forEach((photo, i) => doc.fillShapeWithImage(PETROL.photoFrames[i], photo));

  return doc.toBuffer();
}

export async function generateActivityWordDocument(
  data: ActivityWordExportData,
  template: ActivityReportTemplate
): Promise<Buffer> {
  return template === "ANNUAL" ? fillMaroonForm(data) : fillPetrolForm(data);
}
